async fn write_records(
    State(state): State<Arc<AppState>>,
    Path(collection): Path<String>,
    body: Result<Json<WriteRequest>, JsonRejection>,
) -> Result<Json<WriteResponse>, (StatusCode, Json<ErrorBody>)> {
