    match engine.write_batch(&collection, req.records) {
        Ok(n) => Ok(Json(WriteResponse{collection, written: n})),
        Err(WriteError::Invalid(m)) => Err(err(BAD_REQUEST, m)),
        Err(WriteError::Io(e)) => Err(err(INTERNAL_SERVER_ERROR, format!("failed to persist batch: {e}"))),
