fn check_field(expected: &FieldType, value: &Value, path: &str) -> Result<(), String> {
    let actual = field_type(value).ok_or_else(|| format!("field '{path}': unsupported value type"))?;
    match (expected, &actual) {
        (FieldType::Object(exp_map), FieldType::Object(act_map)) if exp_map != act_map => {
            // recurse to find the differing field
            let obj = value.as_object().unwrap();
            check_schema(exp_map, obj, path)?; // produces specific message
            Ok(())
        }
        _ if *expected == actual => Ok(()),
        _ => Err(format!("field '{path}': expected {}, got {}", name(expected), name(&actual))),
    }
}
```

