fn check_schema(schema: &Schema, obj: &Map<String,Value>, prefix: &str) -> Result<(), String> {
    for key in schema.keys() {
        if !obj.contains_key(key) {
            return Err(format!("field '{}{key}': missing", prefix));
        }
    }
    for (key, val) in obj {
        let path = format!("{prefix}{key}");
        match schema.get(key) {
            None => return Err(format!("field '{path}': not allowed by collection schema")),
            Some(expected) => check_field(expected, val, &path)?,
        }
    }
    Ok(())
}
