fn field_type(v: &Value) -> Option<FieldType> {
    match v {
        Value::Null => Some(FieldType::Null),
        Value::Bool(_) => Some(FieldType::Boolean),
        Value::Number(n) => if n.is_i64() || n.is_u64() { Some(FieldType::Integer) } else { None },
        Value::String(_) => Some(FieldType::String),
        Value::Array(_) => None,
        Value::Object(m) => {
            let mut map = BTreeMap::new();
            for (k, v) in m { map.insert(k.clone(), field_type(v)?); }
            Some(FieldType::Object(map))
        }
    }
}
```

