```rust
impl Engine {
    pub fn load(dir: PathBuf) -> io::Result<Engine> { ... }

    pub fn write_batch(&mut self, name: &str, records: Vec<Value>) -> Result<usize, WriteError> {
        if records.is_empty() {
            return Err(WriteError::Invalid("records must be a non-empty array".into()));
        }
        // validate + build schemas
        let mut schemas = Vec::with_capacity(records.len());
        let mut seen = std::collections::HashSet::new();
        for (i, rec) in records.iter().enumerate() {
            let n = i + 1;
            let obj = rec.as_object().ok_or_else(|| invalid(format!("record {n}: must be a JSON object")))?;
            let id = obj.get("id").ok_or_else(|| invalid(format!("record {n}: missing primary key field 'id'")))?;
            let id = id.as_str().filter(|s| !s.is_empty()).ok_or_else(|| invalid(format!("record {n}: primary key 'id' must be a non-empty string")))?;
            if !seen.insert(id.to_owned()) {
                return Err(invalid(format!("record {n}: duplicate primary key \"{id}\" in batch")));
            }
            let mut schema = Schema::new();
            for (k, v) in obj {
                schema.insert(k.clone(), validate_value(v, k).map_err(|m| invalid(format!("record {n}: {m}")))?);
            }
            schemas.push(schema);
        }
        let expected = match self.collections.get(name) {
            Some(c) => c.schema.clone(),
            None => schemas[0].clone(),
        };
        for (i, rec) in records.iter().enumerate() {
            let obj = rec.as_object().unwrap();
            check_schema(&expected, obj, "").map_err(|m| invalid(format!("record {}: {m}", i + 1)))?;
        }
        // apply upserts on a clone
        let (mut new_records, mut new_index) = match self.collections.get(name) {
            Some(c) => (c.records.clone(), c.index.clone()),
            None => (Vec::new(), HashMap::new()),
        };
        for rec in &records {
            let id = rec["id"].as_str().unwrap().to_owned();
            match new_index.get(&id) {
                Some(&pos) => new_records[pos] = rec.clone(),
                None => { new_index.insert(id, new_records.len()); new_records.push(rec.clone()); }
            }
        }
        // persist first, then commit to memory
        let file = CollectionFile { schema: expected.clone(), records: new_records.clone() };
        let data = serde_json::to_vec_pretty(&file).map_err(io::Error::other)?; // hmm map to Io? WriteError::Io
        write_atomic(&self.collections_dir().join(format!("{name}.json")), &data).map_err(WriteError::Io)?;
        self.collections.insert(name.to_owned(), Collection { schema: expected, records: new_records, index: new_index });
        Ok(records.len())
    }
```

