pub fn save_version(&mut self) -> io::Result<Version> {
    let id = format!("v{}", self.next_version);
    let collections = self.collections.iter()
        .map(|(name, c)| (name.clone(), c.records.clone()))
        .collect();
    let version = Version { id, saved_at: now_rfc3339(), collections };
    let data = serde_json::to_vec_pretty(&version).map_err(io::Error::other)?;
    write_atomic(&self.versions_dir().join(format!("{}.json", version.id)), &data)?;
    self.next_version += 1;
    self.versions.insert(version.id.clone(), version.clone());
    Ok(version)
}
```

