```rust
pub fn load(dir: PathBuf) -> io::Result<Engine> {
    let mut engine = Engine { dir, collections: BTreeMap::new(), versions: BTreeMap::new(), next_version: 1 };
    let cdir = engine.collections_dir();
    if cdir.exists() {
        for entry in fs::read_dir(&cdir)? {
            let path = entry?.path();
            if path.extension().and_then(|e| e.to_str()) != Some("json") { continue; }
            let file: CollectionFile = serde_json::from_slice(&fs::read(&path)?).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("{}: {e}", path.display())))?;
            let name = path.file_stem().unwrap().to_string_lossy().into_owned();
            let mut index = HashMap::new();
            for (pos, rec) in file.records.iter().enumerate() {
                if let Some(id) = rec.get("id").and_then(Value::as_str) {
                    index.insert(id.to_owned(), pos);
                }
            }
            engine.collections.insert(name, Collection { schema: file.schema, records: file.records, index });
        }
    }
    let vdir = engine.versions_dir();
    if vdir.exists() {
        for entry in fs::read_dir(&vdir)? {
            let path = entry?.path();
            if path.extension()... != "json" continue;
            let version: Version = serde_json::from_slice(...)?;
            if let Some(n) = version.id.strip_prefix('v').and_then(|s| s.parse::<u64>().ok()) {
                engine.next_version = engine.next_version.max(n + 1);
            }
            engine.versions.insert(version.id.clone(), version);
        }
    }
    Ok(engine)
}
```

